INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
  (29406, 0, 1, 'The training targets are just down the hill. Come back to me once you''re finished.', 0),
  (29408, 0, 1, 'There will come time when you must trust your instincts and simply act.', 0),
  (29409, 0, 1, 'Our greatest glory is not in never falling, but in getting up every time we do. Jaomin Ro knows this. He finds strength in every defeat.$B$BYou may yet learn that lesson.', 0),
  (29417, 0, 1, 'To not act is to abandon reason.', 0),
  (29418, 1, 1, 'I hope you''re not shy about getting your hands dirty.', 0),
  (29419, 0, 0, 'I should have been more careful. ', 0),
  (29424, 1, 1, 'You needn''t worry about hurting the sprites. They''re really just living plants when it comes down to it - they''ll resprout later.', 0),
  (29523, 1, 1, 'When opportunity rises, it is our responsibility to reach out and grab it. Second guessing is as good as giving up.', 0),
  (29524, 0, 1, 'There is a time for meditation and contemplation, and there is a time for action. Diving the balance between the two is one of the greatest wisdoms we seek.', 0),
  (29662, 0, 0, 'Telling you of my strength means nothing. I must show you.', 0),
  (29664, 0, 1, 'You are not yet ready to face me. First, you must light the braziers.', 0),
  (29677, 1, 0, 'The decision to not return to the pools was a hard one. I don''t think Shu ever truly understood. He does not know what it is to get older and weaker.', 0),
  (29780, 1, 0, 'Following the Huojin discipline often means making the hard decisions. This is one of those moments.', 0),
  (29781, 1, 0, 'I''m somewhat impressed they hadn''t set their village on fire with these things.', 0),
  (29789, 1, 0, 'Rest feels good. The burdens of life have become a great weight after so many years.', 0),
  (29795, 1, 0, 'The Horde does not back down from a fight.', 0),
  (29797, 1, 0, 'Did you find the boxes I spoke of?', 0),
  (29799, 1, 0, 'We need to get the healers to the wound and keep them safe!', 0),
  (30027, 0, 1, 'Picking up your first weapon is also a symbolic gesture. Every $c that leaves these training grounds must be ready to take up arms in defense of their fellow pandaren.', 0),
  (30033, 0, 1, 'Picking up your first weapon is also a symbolic gesture. Every $c that leaves these training grounds must be ready to take up arms in defense of their fellow pandaren.', 0),
  (30590, 1, 0, 'You''re in one piece. That''s a good sign.$B$BDid you get your hands on what I asked for?', 0);
